SELECT MIN(bill_ts) AS min_date, MAX(bill_ts) AS max_date, COUNT(DISTINCT bill_id) AS distinct_bills
FROM store.pos_lines
WHERE bill_ts >= '2026-05-04' AND bill_ts <= '2026-05-31';

SELECT sku, name
FROM store.products
WHERE name ILIKE '%toned%milk%' OR name ILIKE '%milk%toned%';

SELECT SUM(pallets) AS total_pallets
FROM warehouse.shipments
WHERE arrived_ts >= '2026-06-01' AND arrived_ts < '2026-07-01';

SELECT count(DISTINCT date) as days_with_writeoffs
FROM store.write_offs
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT count(*) as grn_lines_june
FROM store.goods_receipts
